package service;
import db.*;import java.sql.*;import java.util.*;import java.math.*;import util.KetNoiDB;
/** S6-04: gợi ý theo hạn dùng, giới hạn đúng vị trí đã hoàn tất soạn. */
public class FefoService{
 public Map<String,Object> suggest(long order,long user,Collection<String> roles)throws SQLException{try(Connection c=KetNoiDB.getConnection()){c.setAutoCommit(false);c.setTransactionIsolation(Connection.TRANSACTION_REPEATABLE_READ);var h=TruyVanDB.one(c,"SELECT o.id,o.code,o.warehouse_id,p.id pick_id FROM orders o JOIN pick_list_orders po ON po.order_id=o.id JOIN pick_lists p ON p.id=po.pick_list_id WHERE o.id=? AND o.status='PICKING' AND p.status='COMPLETED'",order);if(h==null)throw new IllegalArgumentException("Đơn phải hoàn tất soạn và chưa xuất kho");long wh=((Number)h.get("warehouse_id")).longValue();KhoService.access(c,wh,user,roles);
 var lines=TruyVanDB.rows(c,"SELECT l.id,l.product_id,l.quantity,l.conversion_factor,p.sku,p.name FROM order_lines l JOIN products p ON p.id=l.product_id WHERE l.order_id=? ORDER BY l.product_id,l.id",order);
 Map<Long,BigDecimal> taken=new HashMap<>();Map<String,BigDecimal> usedLocations=new HashMap<>();
 for(var l:lines){long product=((Number)l.get("product_id")).longValue();var bins=TruyVanDB.rows(c,"SELECT b.id,b.location_id,b.lot_number,b.expiry_date::text expiry_date,b.on_hand,COALESCE(loc.name,'Chưa phân vị trí') location_name,GREATEST(SUM(pl.actual_quantity)-COALESCE((SELECT -SUM(m.delta) FROM stock_movements m JOIN stock_bins used ON used.id=m.bin_id JOIN pick_list_orders po ON po.order_id=m.document_id WHERE m.kind='SHIPMENT_OUT' AND po.pick_list_id=? AND m.product_id=b.product_id AND used.location_id IS NOT DISTINCT FROM b.location_id),0),0) allowance FROM stock_bins b LEFT JOIN warehouse_locations loc ON loc.id=b.location_id JOIN pick_list_lines pl ON pl.pick_list_id=? AND pl.product_id=b.product_id AND pl.location_id IS NOT DISTINCT FROM b.location_id WHERE b.warehouse_id=? AND b.product_id=? AND b.on_hand>0 AND (b.expiry_date IS NULL OR b.expiry_date>=CURRENT_DATE) GROUP BY b.id,loc.name ORDER BY b.expiry_date NULLS LAST,b.id",h.get("pick_id"),h.get("pick_id"),wh,product);
 BigDecimal remaining=((BigDecimal)l.get("quantity")).multiply((BigDecimal)l.get("conversion_factor"));for(var b:bins){long id=TruyVanDB.id(b);String key=product+":"+b.get("location_id");BigDecimal free=((BigDecimal)b.get("on_hand")).subtract(taken.getOrDefault(id,BigDecimal.ZERO)).max(BigDecimal.ZERO);BigDecimal allowance=((BigDecimal)b.get("allowance")).subtract(usedLocations.getOrDefault(key,BigDecimal.ZERO)).max(BigDecimal.ZERO);BigDecimal q=remaining.min(free).min(allowance);b.put("suggested",q);b.put("available",free);remaining=remaining.subtract(q);taken.merge(id,q,BigDecimal::add);usedLocations.merge(key,q,BigDecimal::add);}l.put("bins",bins);l.put("missing",remaining);}
 c.commit();return Map.of("order",h,"lines",lines);}}
}
